package main

import (
	"fmt"
	"math/rand"
	"net"
	"time"
)

var BANNERS = []string{
	"SSH-2.0-OpenSSH_8.9p1 Ubuntu-3ubuntu0.6\r\n",
	"220 mail.corp.local ESMTP Postfix (Ubuntu)\r\n",
	"* OK [CAPABILITY IMAP4rev1 LITERAL+] Dovecot ready.\r\n",
	"+OK POP3 server ready <1234.1715000000@mail.corp.local>\r\n",
	"220 ftp.corp.local FTP server ready.\r\n",
}

func handleConn(conn net.Conn) {
	defer conn.Close()
	conn.SetDeadline(time.Now().Add(10 * time.Second))
	banner := BANNERS[rand.Intn(len(BANNERS))]
	conn.Write([]byte(banner))
	fmt.Printf("[DEFLECT] %s got banner: %q\n", conn.RemoteAddr(), banner[:20])
}

func main() {
	rand.Seed(time.Now().UnixNano())
	ln, _ := net.Listen("tcp", "127.0.0.1:9999")
	fmt.Println("[*] Fake banner service on :9999")
	for {
		conn, err := ln.Accept()
		if err != nil { continue }
		go handleConn(conn)          // Goroutine per connection
	}
}

